22	/**
23	 * Represents a validated, executable instance of a subagent tool.
24	 *
25	 * This class orchestrates the execution of a defined agent by:
26	 * 1. Initializing the {@link LocalAgentExecutor}.
27	 * 2. Running the agent's execution loop.
28	 * 3. Bridging the agent's streaming activity (e.g., thoughts) to the tool's
29	 * live output stream.
30	 * 4. Formatting the final result into a {@link ToolResult}.
31	 */
32	export class LocalSubagentInvocation extends BaseToolInvocation<
33	  AgentInputs,
34	  ToolResult
35	> {
36	  /**
37	   * @param definition The definition object that configures the agent.
38	   * @param config The global runtime configuration.
39	   * @param params The validated input parameters for the agent.
40	   * @param messageBus Message bus for policy enforcement.
41	   */
42	  constructor(
43	    private readonly definition: LocalAgentDefinition,
44	    private readonly config: Config,
45	    params: AgentInputs,
46	    messageBus: MessageBus,
47	    _toolName?: string,
48	    _toolDisplayName?: string,
49	  ) {
50	    super(
51	      params,
52	      messageBus,
53	      _toolName ?? definition.name,
54	      _toolDisplayName ?? definition.displayName,
55	    );
56	  }
57	
58	  /**
59	   * Returns a concise, human-readable description of the invocation.
60	   * Used for logging and display purposes.
61	   */
62	  getDescription(): string {
63	    const inputSummary = Object.entries(this.params)
64	      .map(
65	        ([key, value]) =>
66	          `${key}: ${String(value).slice(0, INPUT_PREVIEW_MAX_LENGTH)}`,
67	      )
68	      .join(', ');
69	
70	    const description = `Running subagent '${this.definition.name}' with inputs: { ${inputSummary} }`;
71	    return description.slice(0, DESCRIPTION_MAX_LENGTH);
72	  }
73	
74	  /**
75	   * Executes the subagent.
76	   *
77	   * @param signal An `AbortSignal` to cancel the agent's execution.
78	   * @param updateOutput A callback to stream intermediate output, such as the
79	   * agent's thoughts, to the user interface.
80	   * @returns A `Promise` that resolves with the final `ToolResult`.
81	   */
82	  async execute(
83	    signal: AbortSignal,
84	    updateOutput?: (output: string | AnsiOutput) => void,
85	  ): Promise<ToolResult> {
86	    try {
87	      if (updateOutput) {
88	        updateOutput('Subagent starting...\n');
89	      }
90	
91	      // Create an activity callback to bridge the executor's events to the
92	      // tool's streaming output.
93	      const onActivity = (activity: SubagentActivityEvent): void => {
94	        if (!updateOutput) return;
95	
96	        if (
97	          activity.type === 'THOUGHT_CHUNK' &&
98	          typeof activity.data['text'] === 'string'
99	        ) {
100	          updateOutput(`🤖💭 ${activity.data['text']}`);
101	        }
102	      };
103	
104	      const executor = await LocalAgentExecutor.create(
105	        this.definition,
106	        this.config,
107	        onActivity,
108	      );
109	
110	      const output = await executor.run(this.params, signal);
111	
112	      const resultContent = `Subagent '${this.definition.name}' finished.
113	Termination Reason: ${output.terminate_reason}
114	Result:
115	${output.result}`;
116	
117	      const displayContent = `
118	Subagent ${this.definition.name} Finished
119	
120	Termination Reason:\n ${output.terminate_reason}
121	
122	Result:
123	${output.result}
124	`;
125	
126	      return {
127	        llmContent: [{ text: resultContent }],
128	        returnDisplay: displayContent,
129	      };
130	    } catch (error) {
131	      const errorMessage =
132	        error instanceof Error ? error.message : String(error);
133	
134	      return {
135	        llmContent: `Subagent '${this.definition.name}' failed. Error: ${errorMessage}`,
136	        returnDisplay: `Subagent Failed: ${this.definition.name}\nError: ${errorMessage}`,
137	        error: {
138	          message: errorMessage,
139	          type: ToolErrorType.EXECUTION_FAILED,
140	        },
141	      };
142	    }
143	  }
144	}
