import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import type { Transport } from '@modelcontextprotocol/sdk/shared/transport.js';
import type { Tool as McpTool } from '@modelcontextprotocol/sdk/types.js';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';
import type { Config } from '../../config/config.js';
import { getErrorMessage } from '../../utils/errors.js';

export type { Tool as McpTool } from '@modelcontextprotocol/sdk/types.js';

/**
 * The pinned version of the `chrome-devtools-mcp` package that powers the
 * browser agent. Kept as a constant so it can be referenced consistently by
 * both the runtime and the tests.
 */
export const CHROME_DEVTOOLS_MCP_VERSION = '0.6.0';

/** The MCP server name used for policy checks and confirmation prompts. */
export const BROWSER_MCP_SERVER_NAME = 'browser-agent';

/** The name of the on-disk profile directory used for persistent sessions. */
const PERSISTENT_PROFILE_DIR = 'gemini-cli-browser-profile';

/**
 * A single content item returned from an MCP tool call, normalized from the
 * raw MCP SDK response.
 */
export interface McpContentItem {
  type: 'text' | 'image';
  text?: string;
  data?: string;
  mimeType?: string;
}

/**
 * The result of an MCP tool call, normalized from the raw MCP SDK response.
 */
export interface McpToolCallResult {
  content?: McpContentItem[];
  isError?: boolean;
}

/**
 * Manages the lifecycle of a browser automation session via an isolated raw MCP
 * SDK client connected to the `chrome-devtools-mcp` server.
 *
 * Unlike the general MCP tooling in the CLI, this manager owns its own
 * {@link Client} instance directly (rather than going through the shared
 * {@link McpClientManager}) so the experimental browser agent can be spun up
 * and torn down independently.
 */
export class BrowserManager {
  private client: Client | undefined;
  private transport: Transport | undefined;
  private connectionPromise: Promise<void> | undefined;

  constructor(private readonly config: Config) {}

  /**
   * Returns the cached raw MCP SDK {@link Client}, creating it on first use.
   * Subsequent calls return the same instance without constructing a new one.
   */
  async getRawMcpClient(): Promise<Client> {
    if (!this.client) {
      this.client = new Client({
        name: 'gemini-cli-browser-agent',
        version: CHROME_DEVTOOLS_MCP_VERSION,
      });
    }
    return this.client;
  }

  /**
   * Ensures the browser MCP server is spawned and connected. Safe to call
   * multiple times; the connection is only established once.
   */
  async ensureConnection(): Promise<void> {
    if (this.connectionPromise) {
      return this.connectionPromise;
    }
    this.connectionPromise = this.connect();
    try {
      await this.connectionPromise;
    } catch (error) {
      // Allow a future call to retry after a failed connection attempt.
      this.connectionPromise = undefined;
      throw error;
    }
  }

  private async connect(): Promise<void> {
    const { customConfig } = this.config.getBrowserAgentConfig();
    const sessionMode = customConfig.sessionMode ?? 'persistent';
    const headless = customConfig.headless ?? false;
    const profilePath = customConfig.profilePath;

    const args = [
      '-y',
      `chrome-devtools-mcp@${CHROME_DEVTOOLS_MCP_VERSION}`,
      '--experimental-vision',
    ];

    if (headless) {
      args.push('--headless');
    }

    if (profilePath) {
      args.push('--userDataDir', profilePath);
    }

    if (sessionMode === 'isolated') {
      args.push('--isolated');
    } else if (sessionMode === 'existing') {
      args.push('--autoConnect');
    } else if (!profilePath) {
      // Persistent mode with no explicit profile: use a dedicated, reusable
      // profile directory so browser state survives across sessions.
      args.push('--userDataDir', this.getDefaultProfilePath());
    }

    const client = await this.getRawMcpClient();
    this.transport = new StdioClientTransport({
      command: 'npx',
      args,
