class BrowserMcpToolInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly serverToolName: string,
    params: ToolParams,
    messageBus: MessageBus,
    toolName: string,
    toolDisplayName: string,
  ) {
    super(
      params,
      messageBus,
      toolName,
      toolDisplayName,
      BROWSER_MCP_SERVER_NAME,
    );
  }

  getDescription(): string {
    const description = `Browser tool '${this._toolName}' with ${safeJsonStringify(
      this.params,
    )}`;
    return description.slice(0, DESCRIPTION_MAX_LENGTH);
  }

  protected override getPolicyUpdateOptions(
    _outcome: ToolConfirmationOutcome,
  ): PolicyUpdateOptions | undefined {
    return { mcpName: BROWSER_MCP_SERVER_NAME };
  }

  protected override async getConfirmationDetails(
    _abortSignal: AbortSignal,
  ): Promise<ToolCallConfirmationDetails | false> {
    const confirmationDetails: ToolMcpConfirmationDetails = {
      type: 'mcp',
      title: 'Confirm Browser Tool Execution',
      serverName: BROWSER_MCP_SERVER_NAME,
      toolName: this._toolName ?? this.serverToolName,
      toolDisplayName: this._toolDisplayName ?? this._toolName ?? '',
      toolArgs: this.params,
      onConfirm: async (outcome: ToolConfirmationOutcome) => {
        await this.publishPolicyUpdate(outcome);
      },
    };
    return confirmationDetails;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    try {
      const result = await this.browserManager.callTool(
        this.serverToolName,
        this.params,
        signal,
      );

      const textContent = extractText(result.content);

      if (result.isError) {
        return {
          llmContent: `Error: ${textContent}`,
          returnDisplay: textContent,
          error: {
            message: textContent,
          },
        };
      }

      return {
        llmContent: textContent,
        returnDisplay: textContent,
        error: undefined,
      };
    } catch (error) {
      const errorMsg = getErrorMessage(error);
      return {
        llmContent: `Error: ${errorMsg}`,
        returnDisplay: errorMsg,
        error: {
          message: errorMsg,
        },
      };
    }
  }
}

