class BrowserMcpTool extends BaseDeclarativeTool<ToolParams, ToolResult> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly serverToolName: string,
    name: string,
    description: string,
    parametersJsonSchema: unknown,
    messageBus: MessageBus,
  ) {
    super(
      name,
      name,
      description,
      Kind.Other,
      parametersJsonSchema,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: ToolParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ): ToolInvocation<ToolParams, ToolResult> {
    return new BrowserMcpToolInvocation(
      this.browserManager,
      this.serverToolName,
      params,
      messageBus,
      _toolName ?? this.name,
      _toolDisplayName ?? this.displayName,
    );
  }
}

