export async function createMcpDeclarativeTools(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): Promise<DeclarativeTool[]> {
  const discovered = await browserManager.getDiscoveredTools();

  const tools: DeclarativeTool[] = discovered.map(
    (mcpTool) =>
      new BrowserMcpTool(
        browserManager,
        mcpTool.name,
        mcpTool.name,
        mcpTool.description ?? '',
        mcpTool.inputSchema ?? { type: 'object', properties: {} },
        messageBus,
      ),
  );

  // Always include the composite text-entry tool. It is exposed under a stable
  // name and delegates to the server's form-fill capability.
  tools.push(
    new BrowserMcpTool(
      browserManager,
      'fill',
      'type_text',
      'Types text into a page element (or the currently focused element). ' +
        'A convenience wrapper for entering text into inputs and text areas.',
      TYPE_TEXT_SCHEMA,
      messageBus,
    ),
  );

  return tools;
}
