import { LlmRole } from '../../telemetry/llmRole.js';
import type { BrowserManager } from './browserManager.js';

/** The tool name exposed to the model. */
export const ANALYZE_SCREENSHOT_TOOL_NAME = 'analyze_screenshot';

/** The MCP tool used to capture a screenshot of the current page. */
const SCREENSHOT_TOOL_NAME = 'take_screenshot';

interface AnalyzeScreenshotParams {
  instruction: string;
}

const PARAMETERS_SCHEMA = {
  type: 'object',
  properties: {
    instruction: {
      type: 'string',
      description:
        'What to look for or identify in the current screenshot. For ' +
        'example: "Find the coordinates of the blue Submit button".',
    },
  },
  required: ['instruction'],
} as const;

/**
 * Returns true when the error indicates the requested visual model does not
 * exist or the caller lacks permission to use it.
 */
function isModelUnavailableError(message: string): boolean {
  const lower = message.toLowerCase();
  return (
    lower.includes('404') ||
    lower.includes('403') ||
    lower.includes('not found') ||
    lower.includes('permission')
  );
}

class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
    toolName: string,
    toolDisplayName: string,
  ) {
    super(params, messageBus, toolName, toolDisplayName);
  }

  getDescription(): string {
    return `Analyze the current screenshot: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot before invoking the visual model.
    const screenshot = await this.browserManager.callTool(
      SCREENSHOT_TOOL_NAME,
      {},
      signal,
    );

    const imageItem = (screenshot.content ?? []).find(
      (item) => item.type === 'image' && item.data,
    );

    if (!imageItem || !imageItem.data) {
      const message =
        'Failed to capture screenshot. The browser did not return any image ' +
        'content for analysis.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message: 'Failed to capture screenshot' },
      };
    }

    // 2. Send the screenshot and instruction to the configured visual model.
    const { customConfig } = this.config.getBrowserAgentConfig();
    const model = customConfig.visualModel ?? this.config.getModel();

    const contents: Content[] = [
      {
        role: 'user',
        parts: [
          {
            text:
              `Analyze the attached screenshot of a web page and respond to ` +
              `the following instruction:\n\n${this.params.instruction}`,
          },
          {
            inlineData: {
              mimeType: imageItem.mimeType ?? 'image/png',
              data: imageItem.data,
            },
          },
        ],
      },
    ];

    try {
      const response = await this.config.getContentGenerator().generateContent(
        {
          model,
          contents,
        },
        `${this.config.getSessionId()}-analyze-screenshot`,
        LlmRole.UTILITY_TOOL,
      );

      const parts = response.candidates?.[0]?.content?.parts;
      if (!parts || parts.length === 0) {
        const message = 'Visual model returned no analysis.';
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message },
        };
      }

      const text = getResponseText(response) ?? '';
      const llmContent = `Visual Analysis Result\n\n${text}`;
      return {
        llmContent,
        returnDisplay: llmContent,
      };
    } catch (error) {
      const message = getErrorMessage(error);
      if (isModelUnavailableError(message)) {
        const unavailable =
          'Visual analysis model is not available. The configured visual ' +
          'model could not be found or you do not have permission to use it.';
        return {
          llmContent: unavailable,
          returnDisplay: unavailable,
          error: { message: unavailable },
        };
      }

      const failed = `Visual analysis failed: ${message}`;
      return {
        llmContent: failed,
        returnDisplay: failed,
        error: { message: failed },
      };
    }
  }
}

