class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  AnalyzeScreenshotParams,
  ToolResult
> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    params: AnalyzeScreenshotParams,
    messageBus: MessageBus,
    toolName: string,
    toolDisplayName: string,
  ) {
    super(params, messageBus, toolName, toolDisplayName);
  }

  getDescription(): string {
    return `Analyze the current screenshot: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture a screenshot before invoking the visual model.
    const screenshot = await this.browserManager.callTool(
      SCREENSHOT_TOOL_NAME,
      {},
      signal,
    );

    const imageItem = (screenshot.content ?? []).find(
      (item) => item.type === 'image' && item.data,
    );

    if (!imageItem || !imageItem.data) {
      const message =
        'Failed to capture screenshot. The browser did not return any image ' +
        'content for analysis.';
      return {
        llmContent: message,
        returnDisplay: message,
        error: { message: 'Failed to capture screenshot' },
      };
    }

    // 2. Send the screenshot and instruction to the configured visual model.
    const { customConfig } = this.config.getBrowserAgentConfig();
    const model = customConfig.visualModel ?? this.config.getModel();

    const contents: Content[] = [
      {
        role: 'user',
        parts: [
          {
            text:
              `Analyze the attached screenshot of a web page and respond to ` +
              `the following instruction:\n\n${this.params.instruction}`,
          },
          {
            inlineData: {
              mimeType: imageItem.mimeType ?? 'image/png',
              data: imageItem.data,
            },
          },
        ],
      },
    ];

