          contents,
        },
        `${this.config.getSessionId()}-analyze-screenshot`,
        LlmRole.UTILITY_TOOL,
      );

      const parts = response.candidates?.[0]?.content?.parts;
      if (!parts || parts.length === 0) {
        const message = 'Visual model returned no analysis.';
        return {
          llmContent: message,
          returnDisplay: message,
          error: { message },
        };
      }

      const text = getResponseText(response) ?? '';
      const llmContent = `Visual Analysis Result\n\n${text}`;
      return {
