  buildBrowserSystemPrompt,
} from './browserAgentDefinition.js';
import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';

/**
 * The Zod schema describing the browser agent's final output.
 */
const BrowserAgentOutputSchema = z.string();

/**
 * Creates the browser agent definition, connecting to the underlying
 * `chrome-devtools-mcp` server and wrapping its tools.
 *
 * When a visual model is configured, an `analyze_screenshot` tool is included
 * and the system prompt is augmented with vision-specific guidance.
 *
 * @param config The runtime configuration.
 * @param messageBus The message bus used for tool confirmation/policy.
 * @param printOutput An optional callback for surfacing status messages.
 * @returns The agent definition and the browser manager that backs it. Callers
 *   are responsible for calling {@link cleanupBrowserAgent} when done.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{
  definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema>;
  browserManager: BrowserManager;
}> {
  const browserConfig = config.getBrowserAgentConfig();
  const visualModel = browserConfig.customConfig.visualModel;
  const visionEnabled = !!visualModel;

  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  printOutput?.('Browser agent connected to Chrome.');

  const tools: Array<string | FunctionDeclaration | AnyDeclarativeTool> =
    await createMcpDeclarativeTools(browserManager, messageBus);

  if (visionEnabled) {
    tools.push(createAnalyzeScreenshotTool(browserManager, config, messageBus));
  }

  const systemPrompt = buildBrowserSystemPrompt(visionEnabled);

  const definition: LocalAgentDefinition<typeof BrowserAgentOutputSchema> = {
    kind: 'local',
    name: BROWSER_AGENT_NAME,
    displayName: 'Browser Agent',
    description:
      'Autonomously operates a real Chrome browser to accomplish web tasks ' +
      'such as navigating pages, filling forms, and extracting information.',
    experimental: true,
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description:
              'The web task to accomplish, described in natural language.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description:
        'A summary of what was accomplished, including any requested values.',
      schema: BrowserAgentOutputSchema,
    },
    promptConfig: {
      systemPrompt,
      query:
        'Accomplish the following web task:\n<task>\n${task}\n</task>',
    },
    modelConfig: {
      model: browserConfig.model ?? config.getModel(),
    },
    runConfig: {
      maxTimeMinutes: DEFAULT_MAX_TIME_MINUTES,
      maxTurns: DEFAULT_MAX_TURNS,
    },
    toolConfig: {
      tools,
    },
  };

  return { definition, browserManager };
}

/**
 * Tears down the browser agent by closing its browser manager. Never rejects —
 * resolves to `undefined` even if closing throws.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Ignore cleanup errors; teardown should always succeed.
  }
}
