      description:
        'The unique element identifier (from a snapshot) to type into. ' +
        'When omitted, text is typed into the currently focused element.',
    },
    text: {
      type: 'string',
      description: 'The text to type.',
    },
  },
  required: ['text'],
} as const;

/**
 * Creates declarative tools for the browser agent.
 *
 * The returned array contains one wrapped tool for each tool discovered from
 * the MCP server, plus a single composite `type_text` tool that is always
 * included regardless of what the server exposes.
 */
export async function createMcpDeclarativeTools(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): Promise<AnyDeclarativeTool[]> {
  const discovered = await browserManager.getDiscoveredTools();

  const tools: AnyDeclarativeTool[] = discovered.map(
    (mcpTool) =>
      new BrowserMcpTool(
        browserManager,
        mcpTool.name,
        mcpTool.name,
        mcpTool.description ?? '',
        mcpTool.inputSchema ?? { type: 'object', properties: {} },
        messageBus,
      ),
  );

  // Always include the composite text-entry tool. It is exposed under a stable
  // name and delegates to the server's form-fill capability.
  tools.push(
    new BrowserMcpTool(
      browserManager,
      'fill',
      'type_text',
      'Types text into a page element (or the currently focused element). ' +
        'A convenience wrapper for entering text into inputs and text areas.',
      TYPE_TEXT_SCHEMA,
      messageBus,
    ),
  );

  return tools;
}
